<?php
require_once __DIR__ . '/../../cors.php';require_once __DIR__ . '/../../db/db.php';require_once __DIR__ . '/../../reusables/organization_guard.php';header('Content-Type: application/json');$ctx=requireOrganizationAccess($pdo,'rbac.audit_log.read');$org=(int)$ctx['organization_id'];$search=trim((string)($_GET['search']??''));$page=max(1,(int)($_GET['page']??1));$per=20;$off=($page-1)*$per;$where=['a.organization_id=?'];$params=[$org];if($search!==''){$n='%'.$search.'%';$where[]="(a.action LIKE ? OR a.entity_type LIKE ? OR CONCAT_WS(' ',u.first_name,u.last_name) LIKE ?)";array_push($params,$n,$n,$n);} $ws=implode(' AND ',$where);
try{$c=$pdo->prepare("SELECT COUNT(*) FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE $ws");$c->execute($params);$total=(int)$c->fetchColumn();$s=$pdo->prepare("SELECT a.id,a.action,a.entity_type,a.entity_id,a.created_at,CONCAT_WS(' ',u.first_name,u.last_name) actor_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE $ws ORDER BY a.created_at DESC LIMIT $per OFFSET $off");$s->execute($params);$items=$s->fetchAll(PDO::FETCH_ASSOC);$r=$pdo->prepare("SELECT r.id,CONCAT('rbac.',r.table_name,'.',r.action) action,r.table_name entity_type,r.record_id entity_id,r.created_at,CONCAT_WS(' ',u.first_name,u.last_name) actor_name FROM rbac_audit_log r LEFT JOIN users u ON u.id=r.changed_by WHERE r.organization_id=? ORDER BY r.created_at DESC LIMIT 30");$r->execute([$org]);echo json_encode(['success'=>true,'items'=>$items,'rbac_items'=>$r->fetchAll(PDO::FETCH_ASSOC),'pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/$per)),'total'=>$total]]);}catch(Throwable $e){error_log('Org audit failed: '.$e->getMessage());organizationJsonError(500,'Unable to load organization audit activity.');}
